create database customer_behavior;
use customer_behavior;
show databases;

select * from customer_shopping_behavior limit 5;

-- Q1:- WHAT IS THE TOTAL REVENUE GENERATED BY MALE VS FEMALE CUSTOMER
select gender, sum(purchase_amount) as Revenue from customer_shopping_behavior group by gender;

-- Q2:- WHICH CUSTOMER USED A DISCOUNT BUT STILL SPENT MORE THAN THE PURCHASE AMOUNT
select customer_id, purchase_amount from customer_shopping_behavior 
where discount_applied = 'Yes' and purchase_amount >=
(select avg(purchase_amount) from customer_shopping_behavior);

-- Q3:- WHICH ARE THE TOP 5 PRODUCTS WITH THE HIGHEST AVERAGE VIEW RATING?

SELECT item_purchased, round(avg(review_rating),2) as AVERAGE_PRODUCT_RATING from customer_shopping_behavior
group by item_purchased order by avg(review_rating) desc limit 5;

-- Q4:- COMPARE THE PURCHASE AMOUNT BETWEEN STANDARD AND EXPRESS SHIPPING
select shipping_type,round(avg(purchase_amount),2) from customer_shopping_behavior
where shipping_type IN('Standard','Express')
group by shipping_type;

-- Q5 :- DO SUBSCRIBED CUSTOMER SPEND MORE? COMPARE AVERAGE SPEND AND TOTAL REVENUE BETWEEN SUBSCRIBED AND NON-SUBSCRIBED
SELECT subscription_status,count(customer_id) as total_customer, round(avg(purchase_amount),2) as avg_spent,
round(sum(purchase_amount),2) as total_revenue from customer_shopping_behavior
group by subscription_status 
order by total_revenue, avg_spent desc;

-- Q6:- WHICH 5 PRODUCTS HAVE THE HIGHEST PERCENTAGE OF PURCHASES WITH DISCOUNT APPLIED?
select item_purchased, round(100* sum(case when discount_applied= 'Yes' then 1 else 0 end)/count(*),2) as discount_rate
from customer_shopping_behavior group by item_purchased
order by discount_rate desc limit 5;

-- Q7 :- SEGMENTS CUSTOMERS INTO NEW, RETURNING, AND LOYAL BASED ON THEIR TOTAL NUMBER OF PREVIOUS PURCHASES,
-- AND SHOW THE COUNT OF EACH SEGMENT.
with customer_type as (
select customer_id, previous_purchases,
case
when previous_purchases between 0 and 1 then 'New'
when previous_purchases between 2 and 10 then 'Returning'
else 'Loyal'
end as 'Customer_Segment'
from customer_shopping_behavior)
select customer_segment,count(*) as 'Number_of_Customer'
from customer_type 
group by customer_segment;

-- Q8:- WHAT ARE THE TOP 3 MOST PURCHASED PRODUCTS WITHIN EACH CATEGORY.
with item_counts as (
select category, item_purchased, count(customer_id) as total_orders,
row_number() over (partition by category order by count(customer_id) desc) as item_rank
from customer_shopping_behavior
group by category, item_purchased )
select item_rank, category, item_purchased, total_orders from item_counts 
where item_rank <=3;

-- Q9:- ARE THE CUSTOMER WHO ARE REPEATED BUYERS (MORE THAN 5 PREVIOUS PURCHASES) ALSO LIKELY TO SUBSCRIBE?
select subscription_status, count(customer_id) as repeat_buyers
from customer_shopping_behavior
where previous_purchases > 5
group by subscription_status;

-- Q10:- WHAT IS THE REVENUE CONTRIBUTION OF EACH AGE GROUP?
select age_group, sum(purchase_amount) as Total_Revenue
from customer_shopping_behavior
group by age_group order by Total_Revenue desc;

select category, count(customer_id) as customer_count from customer_shopping_behavior
group by category;

select count(*) from customer_shopping_behavior;